package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.tiles.ScreenHousingTextures;
/** Exact released Light menu filter, including raw redirected and company Light entries. */
public final class LightPickerLegacyChecks {
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();JsonArray rows=new JsonArray();int onCount=0,offCount=0;for(int choice=0;choice<ScreenHousingTextures.IDS.length;choice++){boolean include=HousingTextureList.generalTexture(choice)||"Lights".equals(ScreenHousingTextures.category(choice))||ScreenHousingTextures.lightOnly(choice);boolean off=ScreenHousingTextures.visible(choice)&&include,on=off&&!ScreenHousingTextures.isLightOff(choice);if(on)onCount++;if(off)offCount++;JsonObject row=new JsonObject();row.addProperty("choice",choice);row.addProperty("on",on);row.addProperty("off",off);rows.add(row);}String json=rows.toString();java.nio.file.Path output=java.nio.file.Paths.get(args[0]);java.nio.file.Files.createDirectories(output.toAbsolutePath().getParent());java.nio.file.Files.write(output,json.getBytes("UTF-8"));StringBuilder hash=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(json.getBytes("UTF-8")))hash.append(String.format(java.util.Locale.ROOT,"%02x",b&255));StringBuilder prefix=new StringBuilder();JsonArray old=new JsonArray();for(int i=0;i<893;i++)old.add(rows.get(i));for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(old.toString().getBytes("UTF-8")))prefix.append(String.format(java.util.Locale.ROOT,"%02x",b&255));for(int i=893;i<rows.size();i++)if(rows.get(i).getAsJsonObject().get("on").getAsBoolean()||rows.get(i).getAsJsonObject().get("off").getAsBoolean())throw new AssertionError("Door-only addition leaked into Light picker "+i);if(rows.size()!=911||onCount!=263||offCount!=289||!prefix.toString().equals("18c15ed5b1150d747fddf92502d5ca71c5be2d448a4d85703127e34738b62b8e")||!hash.toString().equals("6e84df0bae63a1d7c957fc806bcd5dcdd0e25ba84ba45acdf3f55f04ddcb29d0"))throw new AssertionError("Source Light picker changed "+hash);System.out.println("Actual Light picker PASS choices="+rows.size()+" on="+onCount+" off="+offCount+" golden="+hash);}
}
